sp_widget.client_script:
api.controller = function($window, $timeout, $document) {
  var c = this;
  var HIDE = ['Home', 'Reserve a Car', 'My Reservations', 'File a Complaint'];
  $timeout(function() {
    var links = $document[0].querySelectorAll('header a, .navbar a, nav a, .sp-nav a');
    for (var i = 0; i < links.length; i++) {
      var txt = (links[i].textContent || '').replace(/\s+/g, ' ').trim();
      for (var j = 0; j < HIDE.length; j++) {
        if (txt === HIDE[j]) {
          var el = links[i];
          while (el && el.tagName !== 'LI' && el !== $document[0].body) el = el.parentNode;
          (el && el.tagName === 'LI' ? el : links[i]).style.display = 'none';
          break;
        }
      }
    }
  }, 400);
};

sp_widget.script:
(function() {
  data.links = [];
  var u = gs.getUser();
  try {
    if (u.hasRole('x_2203703_car_re_0.admin')) {
      data.links.push({ label: 'Admin console', id: 'admin_console' });
      data.links.push({ label: 'Desk', id: 'desk' });
    } else if (u.hasRole('x_2203703_car_re_0.receptionist')) {
      data.links.push({ label: 'Desk', id: 'desk' });
      data.links.push({ label: 'My reservations', id: 'my_reservations' });
    } else {
      data.links.push({ label: 'Home', id: 'car_availability' });
    }
  } catch (e) {
    gs.error('Staff Links: ' + e.message);
  }
})();
